const text =
  $input.item.json.input ||
  $input.item.json.message ||
  $input.item.json.chatInput ||
  "";

const match = text.match(/TRZ-SP-\d{3}/i);

$input.item.json.extracted_product_code = match ? match[0].toUpperCase() : null;
$input.item.json.search_mode = match ? "exact_code" : "semantic";

return $input.item;

const content = $json.content || "";

const productNameMatch = content.match(/Product Name:\s*(.*)/);
const descriptionMatch = content.match(/Product Description:\s*(.*)/);
const priceMatch = content.match(/Product Price:\s*(.*)/);
const branchMatch = content.match(/Branch:\s*(.*)/);
const itemsMatch = content.match(/No of Items:\s*(.*)/);

return [
  {
    json: {
      text:
        "Here are the details of your product:\n\n" +
        "- Product Name: " + (productNameMatch ? productNameMatch[1] : "N/A") + "\n" +
        "- Product Description: " + (descriptionMatch ? descriptionMatch[1] : "N/A") + "\n" +
        "- Product Price: " + (priceMatch ? priceMatch[1] : "N/A") + "\n" +
        "- Product Code: " + ($json.product_code || "N/A") + "\n" +
        "- Branch: " + (branchMatch ? branchMatch[1] : "N/A") + "\n" +
        "- No of Items: " + (itemsMatch ? itemsMatch[1] : "N/A") + "\n\n" +
        "I'm here if you'd like help finding another product."
    }
  }
];
